"""生命3：動物の体のつくりと背骨のある動物／背骨のない動物と動物の分類
（ワーク p10〜21、教科書 p36〜43。教科書 p44〜67 の写真は無いので、その範囲はワークのまとめ p16〜17 などを根拠にする）"""
from kbank import T, C, SEQ, N, S, R
from sci import unit

MAJ = '動物の特徴と分類'

def sekitsui():
    u = unit('sekitsui', '動物の体のつくりと背骨のある動物', MAJ, {10, 12, 13, 14, 15, 16, 17, 18, 19, 21},
             '2026-10-05 Claude作成。理科ワークp10（教科書チェック①②）・p12基本①・p13力だめし①②・p14入試(3)・p15用語㉗〜㊱・p16〜17重要事項のまとめ（脊椎動物の分類の表）・p18〜19記述(3)(9)・p21入試問題と、教科書p36〜43（動物の体のつくりと生活・食べ物による体のつくりのちがい・背骨のある動物・観察4・生活場所と体のつくり・呼吸のしかた）を写真で確認して作成。教科書p44〜47の写真は無いため、5つのグループの特徴はワークp16〜17のまとめを根拠にした。')
    q = u.q
    # 動物の体のつくりと生活（教科書p36〜39）
    q(10, '①(1)', '肉食動物', 'ライオンのように、ほかの動物を食べる動物を何というか。', T('肉食動物', 'にくしょくどうぶつ'), '教科書p38：ライオンのようにほかの動物を食べる動物を肉食動物という。', tb=38, tbnote='本文', near=['草食動物'])
    q(10, '①(2)', '草食動物', 'シマウマのように、植物を食べる動物を何というか。', T('草食動物', 'そうしょくどうぶつ'), '教科書p38：シマウマのように植物を食べる動物を草食動物という。', tb=38, tbnote='本文', near=['肉食動物'])
    q(10, '①(3)', '歯のつくり', 'ライオンの大きくするどい犬歯は、どのようなことに適しているか。', R((1, ['獲物', 'えもの']), (1, ['とらえ', '捕らえ', 'つかまえ', '捕まえ'])), '教科書p39：大きくするどい犬歯は獲物をとらえるのに適している。', tb=39, tbnote='本文', example='獲物をとらえること。')
    q(10, '①(3)', '歯のつくり', 'ライオンの臼歯は、どのようなことに適しているか。', R((1, ['皮膚', 'ひふ', '肉', 'にく']), (1, ['骨', 'ほね'])), '教科書p39：臼歯は皮膚や肉をさいて骨をくだくのに適している。', tb=39, tbnote='本文', example='皮膚や肉をさいて、骨をくだくこと。')
    q(10, '①(3)', '歯のつくり', 'シマウマで発達している歯を2つ答えよう。', S(('門歯', 'もんし'), ('臼歯', 'きゅうし')), '教科書p39：シマウマは門歯、臼歯が発達しており、草を切ったり、すりつぶしたりするのに適している。', tb=39, tbnote='本文', near=['臼歯'])
    q(10, '①(3)', '歯のつくり', 'シマウマの門歯と臼歯は、草を食べるときどのようなことに適しているか。', R((1, ['切']), (1, ['すりつぶ', '擦りつぶ', 'すり潰', 'つぶ'])), '教科書p39：草を切ったり、すりつぶしたりするのに適している。', tb=39, tbnote='本文', example='草を切ったり、すりつぶしたりすること。')
    q(10, '①(3)', '歯のつくり', '肉食動物で大きくするどく発達している歯は、門歯・犬歯・臼歯のどれか。', T('犬歯', 'けんし'), '教科書p39図26：ライオンの大きくするどい犬歯は獲物をとらえるのに適している。', tb=39, tbnote='図26 頭部のつくり', near=['門歯', '臼歯'])
    q(10, '①(4)', '目のつき方', 'ライオンの目は、顔の正面と横向きのどちらについているか。', T('正面', 'しょうめん', '顔の正面', '前'), '教科書p39：ライオンの目は顔の正面についている。', tb=39, tbnote='本文', near=['横向き', '横'])
    q(10, '①(4)', '目のつき方', 'ライオンの目が顔の正面についていることは、獲物をとらえるときにどのように役立つか。', R((1, ['立体', 'りったい']), (1, ['距離', 'きょり'])), '教科書p39：両目で立体的に見える範囲が広く、獲物との距離をはかってとらえるのに適している。', tb=39, tbnote='本文', example='両目で立体的に見える範囲が広く、獲物との距離をはかれる。')
    q(10, '①(4)', '目のつき方', 'シマウマの目が横向きについていることは、どのように役立つか。', R((1, ['広範囲', '広い範囲', 'ひろい範囲', '見わた', '見渡']), (1, ['肉食', '捕食', '敵', 'てき', '背後', '早く知', 'はやく知'])), '教科書p39：目は横向きについているため、広範囲を見わたすことができ、肉食動物が背後から近づいてきても早く知ることができる。', tb=39, tbnote='本文', example='広範囲を見わたせるので、肉食動物が背後から近づいても早く知ることができる。')
    q(10, '①(4)', '目のつき方', '両目で立体的に見える範囲が広いのは、ライオンとシマウマのどちらか。', T('ライオン', 'らいおん'), '教科書p39図26：ライオンは目が正面にあり、立体的に見える範囲が広い。', tb=39, tbnote='図26', near=['シマウマ'])
    q(10, '①(4)', '目のつき方', '広範囲を見わたすことができるのは、ライオンとシマウマのどちらか。', T('シマウマ', 'しまうま'), '教科書p39：シマウマは目が横向きについているため、広範囲を見わたすことができる。', tb=39, tbnote='本文', near=['ライオン'])
    q(10, '①(3)', 'あしのつくり', 'ライオンのあしにある、獲物をとらえるときに役立つものは何か。', T('かぎ爪', 'かぎづめ', '鉤爪', 'するどいかぎ爪', '爪', 'つめ'), '教科書p39：ライオンのあしにはするどいかぎ爪があり、速度を上げて走り、獲物をとらえるときに役立つ。', tb=39, tbnote='本文', near=['ひづめ'])
    q(10, '①(3)', 'あしのつくり', 'シマウマのあしにある、長い距離を走り捕食者から逃げるときに役立つものは何か。', T('ひづめ', '蹄', '分厚いひづめ'), '教科書p39：シマウマのあしには分厚いひづめがあり、長い距離を走り、捕食者から逃げるときに役立つ。', tb=39, tbnote='本文', near=['かぎ爪'])
    q(10, '①(1)', '体のつくりと生活', 'ライオンとシマウマは、アフリカのどのような場所にくらしているか。', T('草原地帯', '草原', 'そうげん', 'サバンナ', 'そうげんちたい'), '教科書p38：ライオンもシマウマも、アフリカの草原地帯にくらす大形の動物である。', tb=38, tbnote='本文')
    q(10, '①(1)', '体のつくりと生活', '動物の体は、それぞれの何や生活に合ったつくりをしているか。', T('食べ物', 'たべもの', '食物'), '教科書p39：動物の体は、それぞれの食べ物や生活に合ったつくりをしている。', tb=39, tbnote='本文')
    q(10, '①(1)', '体のつくりと生活', '昆虫の口は、何のちがいによって形がちがうか。', T('食物', '食べ物', 'たべもの', 'しょくもつ'), '教科書p36：図22のように、昆虫の口は食物のちがいによって形がちがう。体のつくりと生活は関係していることが多い。', tb=36, tbnote='図22', near=['大きさ'])
    q(10, '①(1)', '体のつくりと生活', '教科書の図22で、樹液をなめる口をもつ昆虫として示されているのは、カラスアゲハ・カブトムシ・カマキリのどれか。', T('カブトムシ', 'かぶとむし'), '教科書p37図22：カラスアゲハ（花の蜜）、カブトムシ（樹液）、カマキリ（昆虫）。', tb=37, tbnote='図22 昆虫の口の形と食物のちがい', near=['カラスアゲハ', 'カマキリ'])
    q(10, '①(1)', '体のつくりと生活', '教科書の図22で、カマキリが食べている食物は何か。', T('昆虫', 'こんちゅう', '虫'), '教科書p37図22：カマキリは昆虫を食べる。', tb=37, tbnote='図22', near=['樹液', '花の蜜'])
    q(10, '①(1)', '体のつくりと生活', '昆虫の成虫の体は、頭・胸・腹に分かれている。あしは、どこに何本あるか。', R((1, ['胸', 'むね']), (1, ['6本', '６本', '六本', '3対', '３対'])), '教科書p36つながる学び（小3）：昆虫の成虫の体は頭・胸・腹に分かれ、胸に6本のあしとはねがある。', tb=36, tbnote='つながる学び', example='胸に6本')
    q(10, '①(1)', '体のつくりと生活', '動物の体のつくりと生活のしかたを観察するとき、生物を観察する前と後に何をするか。', R((1, ['手']), (1, ['洗', 'あら'])), '教科書p37ためしてみよう：生物を観察する前と後で、手を洗う。', tb=37, tbnote='ためしてみよう', example='手を洗う。')
    q(10, '①(1)', '体のつくりと生活', '動物が運動しているときのようすを、細かい動きまで観察するにはどうすればよいか。教科書のICTでトライの方法を書こう。', R((1, ['動画', 'どうが', 'ビデオ', '撮影', 'さつえい']), (1, ['再生', 'さいせい', 'ゆっくり'])), '教科書p37 ICTでトライ：動物が運動しているときのようすを動画で撮影しておき、後からゆっくりと再生すると、細かな動きを観察できる。', tb=37, tbnote='ICTでトライ', example='動画で撮影して、後からゆっくり再生する。')
    # 背骨のある動物
    q(10, '②(1)', '骨格', '動物がもつ、体を支えるじょうぶな構造を何というか。', T('骨格', 'こっかく'), '教科書p40：動物の体を支えるじょうぶな構造を骨格という。', tb=40, tbnote='本文', near=['背骨', '筋肉'])
    q(10, '②(2)', '脊椎動物', 'ヒトや鳥、魚などのように、背骨をもつ動物を何というか。', T('脊椎動物', 'せきつい動物', 'せきついどうぶつ'), '教科書p40：ヒトや鳥、魚などのように背骨をもつ動物を脊椎動物という。', tb=40, tbnote='本文', near=['無脊椎動物'])
    q(12, '①(1)', '脊椎動物', 'フナ・ウサギ・ハト・イモリ・カメに共通する特徴は何か。', R((1, ['背骨', 'せぼね'])), 'ワークp12①(1)：どれも背骨をもつ（脊椎動物）。', tb=40, tbnote='本文', example='背骨をもつこと。')
    q(10, '観察4', '背骨の観察', '動物の背骨のようすを観察するとき、煮干しはまず何にひたしてやわらかくするか。', R((1, ['水', 'ぬるま湯', 'お湯', '湯'])), '教科書p41観察4：煮干しは、水やぬるま湯に10分ほどひたしてやわらかくする。', tb=41, tbnote='観察4 ステップ1', example='水やぬるま湯')
    q(10, '観察4', '背骨の観察', '観察4で、煮干しを水やぬるま湯にひたす時間はおよそ何分か。', N(10, ['分', '分間', '分ほど']), '教科書p41観察4：水やぬるま湯に10分ほどひたしてやわらかくする。', tb=41, tbnote='観察4 ステップ1', near=['1', '30'])
    q(10, '観察4', '背骨の観察', '観察4で、やわらかくなった部分をとり除いて背骨を観察する。とり除く部分は、おもに何か。', T('筋肉', 'きんにく', '身', '肉'), '教科書p41観察4：手やピンセットを使って、やわらかくなった部分（筋肉など）をとり除き、背骨や背骨のまわりのようすを調べる。', tb=41, tbnote='観察4 ステップ2', near=['背骨'])
    q(10, '観察4', '背骨の観察', '観察4で使う煮干しは、何という魚を干したものか。', T('カタクチイワシ', 'かたくちいわし', 'イワシ'), '教科書p41観察4の準備物：煮干し（カタクチイワシなど）、魚の干物（アジなど）や缶づめ（サバなど）。', tb=41, tbnote='観察4 準備物')
    q(10, '観察4', '背骨の観察', '観察4の別の方法として、体内が透けて見える動物を観察する。教科書で例としてあげられている動物は何か。', T('メダカ', 'めだか'), '教科書p41別の方法にトライ：体内が透けて見える動物（メダカなど）を観察してみよう。', tb=41, tbnote='別の方法にトライ')
    q(10, '②(2)', '脊椎動物', '脊椎動物の背骨は、どのようなつくりをしているか。', R((1, ['骨']), (1, ['組み合わ', 'くみあわ', 'つなが', '連な', 'つらな'])), '教科書p42：脊椎動物は体内に背骨があり、骨がたがいに組み合わさったつくりをしている。', tb=42, tbnote='観察4から', example='骨がたがいに組み合わさったつくり。')
    q(10, '②(2)', '脊椎動物', '脊椎動物がすばやく力強い動きができるのは、背骨のまわりに何が発達しているからか。', T('筋肉', 'きんにく'), '教科書p42：背骨のまわりには筋肉が発達しているので、すばやく力強い動きができる。', tb=42, tbnote='観察4から', near=['骨格'])
    q(10, '②(1)', '透明骨格標本', '教科書の図27「透明骨格標本」は、何で処理して骨格などの体の中のつくりが見えるように染色したものか。', T('薬品', 'やくひん'), '教科書p40図27：薬品で処理し、骨格などの体の中のつくりが見えるように染色している。', tb=40, tbnote='図27')
    q(10, '②(2)', '背骨のない動物', '教科書の図27の透明骨格標本のうち、背骨がない動物を次からすべて選ぼう。\nア ホッコクアカエビ　イ アジ　ウ スルメイカ　エ ウズラ', C('アウ'), '教科書p40〜41図27：背骨がないのはホッコクアカエビ・スルメイカ。アジ・ウズラは脊椎動物。', tb=41, tbnote='図27', near=['ア', 'ウ'])
