    q(10, '②(3)', '生活場所と体のつくり', 'ワシのように、空を飛んで移動する脊椎動物には何があるか。', T('翼', 'つばさ'), '教科書p42：ワシのように翼があり、空を飛んで移動するものもいる。', tb=42, tbnote='生活場所と体のつくり', near=['ひれ', 'あし'])
    q(10, '②(3)', '呼吸のしかた', '一生を水中で生活する脊椎動物の多くは、何で呼吸するか。', T('えら', '鰓', 'エラ'), '教科書p42：一生を水中で生活する脊椎動物の多くは、えらで呼吸する。', tb=42, tbnote='呼吸のしかた', near=['肺', '皮膚'])
