    q(10, '②(8)', '卵生', '親が卵を産み、卵から子がかえる生まれ方を何というか。', T('卵生', 'らんせい'), 'ワークp16〜17まとめ：卵生＝卵を産んで卵から子がかえる生まれ方。', near=['胎生'])
